import React from 'react';
import integrity from '../data/integrity.json';
import { facts } from '../data/facts';

/**
 * Live evidence-integrity counts, generated by scripts/check-data.mjs at build time
 * (so they cannot be hand-edited into a false "PASS").
 */
export function IntegrityPanel() {
  const t = integrity.factsByTier as Record<string, number>;
  const tiles = [
    { label: 'Facts in the data layer', value: integrity.facts, note: `Tier 1: ${t['1']} · Tier 2: ${t['2']} · Tier 0: ${t['0']}` },
    { label: 'Contradictions found', value: integrity.contradictions, note: 'Same fact with two values' },
    { label: 'Deep-linked sources', value: `${integrity.deepLinkedSources} / ${integrity.sources}`, note: 'Others link to a home page only' },
    { label: 'Figures not yet in the data layer', value: integrity.hardcodedLiteralsRemaining, note: `In ${integrity.componentsWithLiterals} components; being migrated` },
  ];
  const gaps = facts.filter((f) => f.tier === 0);

  return (
    <section aria-labelledby="integrity-heading" className="space-y-3">
      <h4 id="integrity-heading" className="font-display text-paper text-base font-semibold">
        Evidence integrity (computed at build)
      </h4>
      <dl className="grid grid-cols-2 lg:grid-cols-4 gap-2">
        {tiles.map((x) => (
          <div key={x.label} className="rounded border border-hairline bg-ink p-3">
            <dt className="text-xs text-sage">{x.label}</dt>
            <dd className="font-mono text-xl text-paper tabular-nums">{x.value}</dd>
            <dd className="text-[11px] text-sage-dim">{x.note}</dd>
          </div>
        ))}
      </dl>
      <div className="rounded border border-brick/40 bg-brick/10 p-3">
        <p className="text-xs text-paper font-semibold">Tier 0 gaps the owner must close</p>
        <ul className="mt-1 list-disc pl-5 text-xs text-sage space-y-0.5">
          {gaps.map((g) => (
            <li key={g.id}>
              {g.label}
              {g.method && <span className="text-sage-dim"> — {g.method}</span>}
            </li>
          ))}
        </ul>
      </div>
      <p className="font-mono text-[11px] text-sage-dim">Data version {integrity.dataHash}</p>
    </section>
  );
}
